# ============================================================================
# Small generic helpers
# ============================================================================
def load_json(path: str) -> Optional[Any]:
    if not os.path.exists(path):
        return None
    try:
        with open(path, "r") as fh:
            return json.load(fh)
    except Exception as exc:  # noqa: BLE001 — never let one bad file kill the export
        print(f"  ! could not parse {path}: {exc}")
        return None


def git_short_sha() -> str:
    """READ-only git: short SHA for provenance. Never mutate the repo."""
    try:
        out = subprocess.run(
            ["git", "rev-parse", "--short", "HEAD"],
            capture_output=True, text=True, timeout=10,
        )
        return out.stdout.strip() or "unknown"
    except Exception:  # noqa: BLE001
        return "unknown"


def num(v: Any) -> Optional[float]:
    """Coerce a value (possibly a display string like '13,360' or '£8.15 M') to float."""
    if v is None:
        return None
    if isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        s = v.strip().replace(",", "").replace("£", "").replace("$", "")
        m = re.search(r"-?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?", s)
        if m:
            try:
                return float(m.group(0))
            except ValueError:
                return None
    return None


def qval(quantities: Dict[str, Any], key: str) -> Optional[float]:
    """Numeric value of a contract quantity (handles {value:..} or bare scalar)."""
    if key not in quantities:
        return None
    v = quantities[key]
    return num(v.get("value") if isinstance(v, dict) else v)


def qunit(quantities: Dict[str, Any], key: str) -> str:
    v = quantities.get(key)
    return (v.get("unit", "") if isinstance(v, dict) else "") or ""


def set_widths(ws: Worksheet, widths: Dict[str, float]) -> None:
    for col, w in widths.items():
        ws.column_dimensions[col].width = w


# Per-tab deterministic scorecard (Tristan 2026-06-26): set in build() from dossier_audit.tab_scores,
# keyed by Excel sheet name. title_row stamps each tab's score banner from this — every tab shows its
# deterministic quality vs the ≥8 floor, on the tab.
_TAB_SCORES: dict = {}
_RUN_DIR: str = ""           # set in build() so the banner can read parts-ledger coverage
_COV_CACHE: dict = {}


def _ledger_coverage(run_dir: str) -> dict:
    if run_dir in _COV_CACHE:
        return _COV_CACHE[run_dir]
    cov = {}
    try:
        d = load_json(os.path.join(run_dir, "parts-ledger.json")) or {}
        cov = d.get("coverage_by_drawing") or {}
    except Exception:  # noqa: BLE001
        cov = {}
    _COV_CACHE[run_dir] = cov
    return cov


_LITTER_CACHE: dict = {}
_SHAPE_MM_CACHE: dict = {}
_VISION_CACHE: dict = {}


def _render_vision_verdict(run_dir: str):
    """SIGHT: read the vision critic's verdict on the render (render-vision-critique.json), if a vision
    model has looked. {ok, broken, defects, model} or None. Deterministic READ of the delivered verdict
    — the non-deterministic vision CALL happens once upstream (the chain / render_vision_critic.py)."""
    if run_dir in _VISION_CACHE:
        return _VISION_CACHE[run_dir]
    res = None
    try:
        with open(os.path.join(run_dir, "render-vision-critique.json"), "r", encoding="utf-8") as _fh:
            res = json.load(_fh)
    except Exception:  # noqa: BLE001
        res = None
    _VISION_CACHE[run_dir] = res
    return res


def _manifest_litter(run_dir: str):
    """SIGHT: default-size litter score for the delivered parts-manifest (cached). The engine reading
    its OWN rendered geometry — a render/GA tab can't be a genuine ≥8 while most objects are default
    boxes (Tristan saw 'tiny identical boxes')."""
    if run_dir in _LITTER_CACHE:
        return _LITTER_CACHE[run_dir]
    res = None
    try:
        sys.path.insert(0, os.path.join(os.path.dirname(__file__), "lib"))
        import manifest_sight as _ms
        res = _ms.litter_from_path(os.path.join(run_dir, "parts-manifest.json"))
    except Exception:  # noqa: BLE001
        res = None
    _LITTER_CACHE[run_dir] = res
    return res


_DIV_CACHE: dict = {}


def _manifest_shape_mismatch(run_dir: str):
    """SIGHT: read the DELIVERED parts-manifest and flag electrical parts drawn as process vessels
    (the stray-beam class). Cached. {count, parts, status} or None."""
    if run_dir in _SHAPE_MM_CACHE:
        return _SHAPE_MM_CACHE[run_dir]
    res = None
    try:
        sys.path.insert(0, os.path.join(os.path.dirname(__file__), "lib"))
        import manifest_sight as _ms
        with open(os.path.join(run_dir, "parts-manifest.json"), "r", encoding="utf-8") as _fh:
            res = _ms.shape_type_mismatches(json.load(_fh))
    except Exception:  # noqa: BLE001
        res = None
    _SHAPE_MM_CACHE[run_dir] = res
    return res


def _manifest_div(run_dir: str):
    """SIGHT: do ≥2 parts-manifests in the run disagree on positions (GA reads one, render another →
    GA-top ≠ render-top)? Cached."""
    if run_dir in _DIV_CACHE:
        return _DIV_CACHE[run_dir]
    res = None
    try:
        sys.path.insert(0, os.path.join(os.path.dirname(__file__), "lib"))
        import manifest_sight as _ms
        res = _ms.manifest_divergence(run_dir)
    except Exception:  # noqa: BLE001
        res = None
    _DIV_CACHE[run_dir] = res
    return res


def _aux_tab_score(title: str, run_dir: str):
    """A deterministic quality score for a DRAWING / RENDER / META sheet that the per-tab scorecard
    (the 16 data tabs) doesn't cover — so EVERY sheet shows a quality number (Tristan 2026-06-27).
    Drawings score from parts-ledger drawing coverage (an EMPTY P&ID → 0); renders use coverage as a
    proxy + flag that object-level visual quality is an open check (no fake clean PASS); ⚠ Checks uses
    the invariant pass-rate; ⚠ Audit the ship verdict. Pure navigation tabs (Contents) return None."""
    t = (title or "").lower()
    if title == _AUDIT_SHEET_TITLE:
        # the embedded-operand register scores via its OWN content mechanism (_MECH_ONLY_TABS
        # + per-row Cell check formulas) — the 'audit' keyword branch below is the dossier
        # ship-verdict fallback and must not capture it
        return None
    cov = _ledger_coverage(run_dir)

    def _cov(key: str, label: str, advisory: str = ""):
        c = cov.get(key)
        if not isinstance(c, dict):
            return None
        pct = c.get("pct")
        if not isinstance(pct, (int, float)):
            return None
        sc = max(0, min(10, round(pct / 10)))
        iss = []
        if advisory:
            iss.append(advisory)
            # HONEST CAP (Tristan 2026-06-27): an ADVISORY = a dimension the engine did NOT verify
            # (here, object-level VISUAL quality — coverage being 100% says the tags are present, NOT
            # that the picture is right). An unverified dimension means the sheet is NOT verified-perfect
            # and CANNOT score 10; nor can it be a confident ≥8 PASS until something actually LOOKS at it
            # (the SIGHT vision-critic). Cap at 7 (FAIL) so an unverified render never reads as shippable.
            # Earning ≥8 requires a real visual check that clears, which removes the advisory.
            sc = min(sc, 7)
        st = "PASS" if sc >= 8 else "FAIL"
        iss.append(f"{label} part coverage {c.get('present')}/{c.get('expected')} ({pct:.0f}%)"
                   + ("" if pct >= 80 else " — under-covered: the drawing must render its parts so their tags match the BoM"))
        return {"score": sc, "target": 8, "status": st, "issues": iss,
                "fix": "object-level visual quality is UNVERIFIED — run the vision critic on the render so a 5-second human-glance defect is caught before ship (then this advisory clears); also keep coverage ≥ 80%"}

    if t == "drawings" or "drawing register" in t:
        # DRAWING REGISTER (reviewers 2026-07-02) — deterministic integrity check of the
        # register itself: every A1 sheet PDF it lists must EXIST on disk at build time,
        # and every print set must meet the 2.5 mm ISO 3098 lettering bar. A registered
        # file missing from disk is a broken deliverable → FAIL, honestly flagged.
        regs = _drawing_register_rows(run_dir or "")
        if not regs:
            return None
        listed = [f for rr in regs for f in rr["files"]]
        missing = [f for rr in regs for f in rr["missing"]]
        with_a1 = [rr for rr in regs if rr["files"]]
        if not with_a1:
            return {"score": 2, "target": 8, "status": "FAIL",
                    "issues": ["no print-ready A1 PDF set exists for ANY drawing — the register has nothing to point at"],
                    "fix": "run the drawing generators (a1_print.export_a1 in draw_pid / draw_bfd / draw_single_line / draw_ga)"}
        if missing:
            sc = min(6, max(0, round(10 * (len(listed) - len(missing)) / max(1, len(listed)))))
            return {"score": sc, "target": 8, "status": "FAIL",
                    "issues": [f"{len(missing)} of {len(listed)} registered A1 sheet PDF(s) MISSING on disk: "
                               + ", ".join(missing[:4])],
                    "fix": "re-run the drawing generators so every registered sheet PDF exists next to its SVG"}
        below = [rr["no"] for rr in with_a1 if rr.get("meets_bar") is False]
        if below:
            return {"score": 7, "target": 8, "status": "FAIL",
                    "issues": ["print legibility below the 2.5 mm ISO 3098 bar on: " + ", ".join(below)],
                    "fix": "a1_print pagination must split those drawings onto more A1 sheets"}
        no_a1 = [rr["no"] for rr in regs if not rr["files"]]
        iss = [f"{len(with_a1)} drawing(s) registered with {len(listed)} print-ready A1 sheet PDF(s), "
               f"all present on disk, lettering ≥2.5 mm"]
        sc = 10
        if no_a1:
            sc = 8
            iss.append("no A1 print set yet for: " + ", ".join(no_a1) + " (PNG/SVG master only)")
        return {"score": sc, "target": 8, "status": "PASS", "issues": iss,
                "fix": "" if sc == 10 else "wire a1_print.export_a1 into the remaining generator(s)"}
    if "p&id" in t or t == "pid":
        return _cov("pid", "P&ID")
    if "block flow" in t or "bfd" in t:
        return _cov("block-flow-diagram", "Block-flow")
    def _cap_litter(base):
        """A render / GA drawing reflects the parts-manifest geometry, so default-size LITTER and a
        MANIFEST DIVERGENCE (GA reads one manifest, the render another → different layouts) both cap its
        score — it cannot be a genuine ≥8 while most objects are default boxes OR the two top-views can
        legitimately disagree (SIGHT)."""
        if not isinstance(base, dict):
            return base

        def _cur(b):  # current score, treating a legit 0 as 0 (NOT `or 10` — that masks a real 0)
            s = b.get("score")
            return s if isinstance(s, (int, float)) else 10

        # LITTER first, then DIVERGENCE — so the more-fundamental divergence issue leads the banner.
        lit = _manifest_litter(run_dir)
        if isinstance(lit, dict) and isinstance(lit.get("score"), (int, float)) and lit["score"] < _cur(base):
            w = lit.get("worst") or {}
            base["score"] = lit["score"]
            base["status"] = "PASS" if lit["score"] >= 8 else "FAIL"
            base["issues"] = ([f"default-size LITTER: {lit['litter_parts']}/{lit['parts']} parts "
                               f"({int(lit['litter_ratio']*100)}%) share a default box — worst: "
                               f"{w.get('n_distinct','?')} distinct parts @ {w.get('dims','?')} "
                               f"(e.g. {', '.join((w.get('examples') or [])[:3])}); the geometry "
                               f"generator must derive real per-part dims"] + (base.get("issues") or []))[:6]
            base["fix"] = "geometry generator must size each part from its real dims, not a shared default box"
        div = _manifest_div(run_dir)
        if isinstance(div, dict) and div.get("diverged"):
            base["score"] = 0
            base["status"] = "FAIL"
            base["issues"] = ([f"LAYOUT DIVERGENCE: {div.get('detail', '')}"] + (base.get("issues") or []))[:6]
            base["fix"] = div.get("fix", base.get("fix", ""))
        # WRONG-SHAPE (council typed-shape gate 2026-06-27): a render/GA with an electrical part drawn
        # as a process VESSEL (a power feed as a 2.7 m horizontal cylinder = the stray red beam) cannot
        # be a clean pass. Read the DELIVERED manifest, FAIL on any mismatch. Deterministic; the
        # source fix (classify_shape) prevents it, this enforces it on the rendered artefact.
        stm = _manifest_shape_mismatch(run_dir)
        if isinstance(stm, dict) and stm.get("count"):
            ex = ", ".join(f"{p['name']}→{p['shape']}" for p in stm.get("parts", [])[:3])
            base["score"] = min(_cur(base), 4)
            base["status"] = "FAIL"
            base["issues"] = ([f"WRONG SHAPE: {stm['count']} electrical part(s) rendered as a process "
                               f"vessel (the stray-beam defect): {ex}"] + (base.get("issues") or []))[:6]
            base["fix"] = "classify_shape must map an electrical/power-connection part to a cabinet/box, not a vessel"
        return base

    if "general arrangement" in t or t.startswith("ga "):
        return _cap_litter(_cov("general-arrangement", "GA"))
    if "single-line" in t or "single line" in t:
        return _cov("single-line-diagram", "Single-line")
    if "isometric" in t:
        return _cov("isometric-index", "Isometric")
    if "render" in t or "interior layout" in t or "building exterior" in t:
        # VISION VERDICT (Tristan 2026-06-28): if a vision critic has actually LOOKED at the render
        # (render-vision-critique.json), its verdict replaces the blanket 'visual quality unverified'
        # advisory. broken → FAIL with the named defect (flag-only: it can only CAP, never lift).
        # clean → the visual dimension is VERIFIED, so NO advisory and the render can earn ≥8 on its
        # deterministic checks (coverage/litter/shape). absent → keep the advisory (honest-cap → 7).
        _vv = _render_vision_verdict(run_dir)
        _vv_defects = (_vv.get("defects") or []) if isinstance(_vv, dict) else []
        # DETERMINISTIC backstop FIRST: a real electrical-part-drawn-as-a-vessel (the stray-beam defect)
        # caps the render to 4 regardless of the vision critic — so relaxing an UNSUBSTANTIATED vision
        # verdict below can never let a genuine structural defect pass.
        _stm = _manifest_shape_mismatch(run_dir)
        if isinstance(_stm, dict) and _stm.get("count"):
            base = _cap_litter(_cov("blender", "Render"))
            if isinstance(base, dict):
                _ex = ", ".join(f"{p['name']}→{p['shape']}" for p in _stm.get("parts", [])[:3])
                base["score"] = min(base.get("score", 10) if isinstance(base.get("score"), (int, float)) else 10, 4)
                base["status"] = "FAIL"
                base["issues"] = ([f"WRONG SHAPE: {_stm['count']} electrical part(s) rendered as a process vessel (the stray-beam defect): {_ex}"] + (base.get("issues") or []))[:6]
                base["fix"] = "classify_shape must map an electrical/power-connection part to a cabinet/box, not a vessel"
            return base
        # VISION VERDICT: a 'broken' flag only HARD-CAPS when it NAMES a concrete defect. An LLM
        # 'broken=True' with EMPTY defects is unsubstantiated — a false FAIL is as dishonest as a false
        # PASS (Tristan 2026-06-30); the deterministic shape/litter/coverage checks are the real gate.
        if isinstance(_vv, dict) and _vv.get("ok") and _vv.get("broken") is True and _vv_defects:
            base = _cap_litter(_cov("blender", "Render"))
            if isinstance(base, dict):
                _df = "; ".join(str(d) for d in _vv_defects[:3])
                base["score"] = min(base.get("score", 10) if isinstance(base.get("score"), (int, float)) else 10, 4)
                base["status"] = "FAIL"
                base["issues"] = ([f"VISION CRITIC flagged a visible defect: {_df} — the render is not "
                                   f"clean (model: {_vv.get('model', '?')})"] + (base.get("issues") or []))[:6]
                base["fix"] = "fix the geometry/routing that produces the flagged defect, then the vision critic clears"
            return base
        if isinstance(_vv, dict) and _vv.get("ok") and (_vv.get("broken") is False or not _vv_defects):
            # VERIFIED clean, OR broken-but-unsubstantiated (no named defect) → score on the DETERMINISTIC
            # checks (coverage/litter/shape) only; the vision critic cannot drag a deterministically-clean
            # render to a FAIL on a verdict it could not substantiate.
            return _cap_litter(_cov("blender", "Render"))
        return _cap_litter(_cov("blender", "Render",
                    advisory="ADVISORY: object-level visual quality is UNVERIFIED — no vision critic has looked at this render (run render_vision_critic)"))
    if "checks" in t:  # ⚠ Checks — deterministic-invariant pass rate
        try:
            import deterministic_checks_lib as _dcl
            _chk = _dcl.run_all_checks(run_dir, None)
            _n = len(_chk)
            _nf = len([c for c in _chk if str(getattr(c, "status", "")).upper() == "FAIL"])
            if _n:
                # ANY failing invariant means this tab is NOT clean — never round a handful of
                # fails away into a green 10 (the fake-8). 0 fails → 10; else a hard FAIL.
                _sc = 10 if _nf == 0 else max(0, 8 - 2 * _nf)
                return {"score": _sc, "target": 8, "status": "PASS" if _sc >= 8 else "FAIL",
                        "issues": [f"{_nf} of {_n} deterministic invariants FAIL — this tab cannot be a clean 10 over failures"] if _nf else [f"{_n}/{_n} invariants pass"],
                        "fix": "fix each failing invariant at source"}
        except Exception:  # noqa: BLE001
            pass
        return None
    if "audit" in t:  # ⚠ Audit — the dossier ship verdict = does every scored tab reach ≥8?
        # ONE FLOOR (fix 3, reviewers 2026-07-02): this fallback score IS the weakest
        # tab score — never a derived max(2, …) number no other surface quotes. (The
        # canonical 'Quality & Audit' entry is set in build() from compute_verdict; this
        # branch only serves a direct _aux_tab_score call before that entry exists.)
        _scored = [v.get("score") for v in _TAB_SCORES.values() if isinstance(v.get("score"), (int, float))]
        if _scored:
            _worst = min(_scored)
            _ok = _worst >= 8
            return {"score": 8 if _ok else _worst, "target": 8, "status": "PASS" if _ok else "FAIL",
                    "issues": [] if _ok else [f"the dossier does NOT ship — the weakest tab scores {_worst}/10; every tab must reach ≥8"],
                    "fix": "resolve the failing tabs (see the per-tab punch-list / Quality & Audit findings)"}
        return None
    if "hvac" in t:
        # Deterministic HVAC check (Tristan 2026-06-27 — close the last UNSCORED tab). The score
        # depends on the design's actual HVAC SCOPE, read from the contract:
        #   • A design with a real HVAC / ventilation / cooling DUTY (an hvac/vent/cooling/heat-load
        #     quantity) must REPRESENT that equipment — score from the HVAC drawing's part coverage.
        #   • A design with NO HVAC duty (a process / fluid plant whose climate hardware is explicitly
        #     supplied by others — the Codema brief states exactly this) has nothing to mis-represent:
        #     the HVAC sheet is an honest building-ventilation / out-of-scope note → PASS (it is
        #     class-correct, not a fake clean — there IS no HVAC equipment to fail on).
        # Universal — keyed on the presence of an HVAC duty signal, no class table.
        st_path = os.path.join(run_dir or "", "state.json")
        has_hvac_duty = False
        try:
            with open(st_path, "r", encoding="utf-8") as _fh:
                _st = json.load(_fh)
            _q = ((_st.get("orchestratorContract") or {}).get("quantities")
                  or (_st.get("engineeringContract") or {}).get("quantities") or {})
            has_hvac_duty = any(
                re.search(r"hvac|ventilation_supply_air|cooling_load|chiller|space_heating|"
                          r"air_change|supply_air_m3_h|extract_air", str(k), re.I)
                and isinstance((v or {}).get("value"), (int, float)) and (v or {}).get("value")
                for k, v in _q.items())
        except Exception:  # noqa: BLE001
            pass
        if has_hvac_duty:
            _hc = _cov("hvac", "HVAC")
            if _hc is not None:
                return _hc
            # DIRECT deterministic coverage (BESS cross-val 2026-07-03): the parts-ledger
            # computes no 'hvac' rep yet, but the drawing IS delivered — score the tab on
            # what it shows instead of a flat unscored-6. Coverage = fraction of the
            # design's HVAC/cooling-duty BoM parts named on drawings/hvac-layout.svg
            # (plural-insensitive token overlap, same spirit as parts_ledger.covered).
            # Universal: keyed on the HVAC/cooling service family, no class table; a
            # class with no such parts or no drawing falls through to the honest FAIL.
            _svgp = os.path.join(run_dir or "", "drawings", "hvac-layout.svg")
            _hvac_fam = re.compile(
                r"hvac|chiller|\bcool|coolant|cold[ -]?plate|air[ -]?handl|\bahu\b|"
                r"air[ -]?condition|\bac unit\b|ventilat|vent[ -]?fan|extract|supply[ -]?air|"
                r"\bduct\b|damper|louvre|condensate|fan[ -]?coil|radiator|glycol|expansion tank",
                re.I)
            try:
                with open(st_path, "r", encoding="utf-8") as _fh:
                    _st2 = json.load(_fh)
                _hvac_parts = sorted({str(r.get("requirement") or r.get("part") or "").split("·")[0].strip()
                                      for r in (_st2.get("requirementsBom") or [])
                                      if isinstance(r, dict)
                                      and _hvac_fam.search(str(r.get("requirement") or r.get("part") or ""))})
                _hvac_parts = [p for p in _hvac_parts if p]
            except Exception:  # noqa: BLE001
                _hvac_parts = []
            _svg_txt = ""
            try:
                _svg_txt = " ".join(re.findall(r">([^<>]+)<", open(_svgp).read())).lower()
            except Exception:  # noqa: BLE001
                _svg_txt = ""
            if _hvac_parts and _svg_txt:
                _sing = lambda s: re.sub(r"s\b", "", s.lower())  # noqa: E731
                _svg_sing = _sing(_svg_txt)
                _generic = {"unit", "system", "main", "panel", "skid", "rack", "plant"}
                def _on_drawing(pn: str) -> bool:
                    toks = [w for w in re.findall(r"[a-z]{4,}", pn.lower()) if w not in _generic]
                    hits = sum(1 for w in toks if _sing(w) in _svg_sing)
                    return bool(toks) and hits >= max(1, (len(toks) + 1) // 2)
                _shown = [p for p in _hvac_parts if _on_drawing(p)]
                _missing = [p for p in _hvac_parts if p not in _shown]
                _pct = 100.0 * len(_shown) / len(_hvac_parts)
                _sc = max(0, min(10, round(_pct / 10)))
                return {"score": _sc, "target": 8,
                        "status": "PASS" if _sc >= 8 else "FAIL",
                        "issues": [f"HVAC drawing coverage {len(_shown)}/{len(_hvac_parts)} "
                                   f"({_pct:.0f}%) of the design's HVAC/cooling-duty parts"
                                   + (f" — MISSING from the drawing: {', '.join(_missing[:5])}"
                                      if _missing else "")],
                        "fix": ("the HVAC drawing generator must draw the design's full HVAC scope "
                                "(air-side AC / ventilation / ducting as well as the coolant loop)"
                                if _missing else "")}
            return {
                "score": 6, "target": 8, "status": "FAIL",
                "issues": ["the design carries an HVAC duty but the HVAC drawing has no scored coverage — "
                           "the drawing must represent the ventilation / cooling equipment"],
                "fix": "the HVAC drawing generator must emit the ventilation/cooling equipment tags"}
        # HONEST score (Tristan 2026-06-27): an OUT-OF-SCOPE disclosure is class-correct and ships, but
        # it is NOT a verified-perfect 10 — there is no HVAC engineering ON the sheet to make it a "wow".
        # Cap at 8 (a clean PASS for a correctly-scoped sheet) — never inflate a disclosure to 10.
        return {"score": 8, "target": 8, "status": "PASS",
                "issues": ["HVAC is OUT OF SCOPE for this process / fluid plant — its climate hardware "
                           "(heating / ventilation / cooling) is supplied by others (per the brief); the "
                           "sheet honestly documents building-ventilation only, with no HVAC equipment to "
                           "size or mis-represent. Class-appropriate, not a coverage gap."],
                "fix": "none — an HVAC duty would switch this to a coverage-scored check automatically"}
    return None  # Contents / ⭐ Scorecard navigation tabs


def _tab_quality_banner(title: str):
    """The score-CHIP spec ({text, fill, height}) for a sheet — score + the scoring
    formula with LIVE COUNTS (the tab's own basis) + a pointer to Quality & Audit.
    None only when the tab has no score entry at all (the no-silent-default assertion
    turns that into a build error before any chip is stamped)."""
    v = _TAB_SCORES.get(title)
    if not isinstance(v, dict):
        v = _aux_tab_score(title, _RUN_DIR)   # drawing / render / meta sheets → on-the-fly score
    if not isinstance(v, dict):
        return None
    tgt = v.get("target", 8)
    status = v.get("status")
    if status == "UNSCORED":
        return {
            "text": f"⬤ TAB QUALITY — UNSCORED: no deterministic check covers this tab yet, so it cannot be certified ≥{tgt}. {v.get('fix', '')}",
            "fill": FILL_ADVISORY, "height": 30,
        }
    sc = v.get("score")
    sc_txt = f"{sc:g}" if isinstance(sc, (int, float)) else str(sc)
    basis = str(v.get("basis") or "").strip()
    basis_short = (basis[:170] + "…") if len(basis) > 171 else basis
    issues = v.get("issues") or []
    tail = (f"  →  {issues[0]}" if (status == "FAIL" and issues) else "")
    return {
        "text": (f"⬤ TAB QUALITY {sc_txt}/10 · {status} (target ≥{tgt})"
                 + (f" · {basis_short}" if basis_short else "")
                 + " · full audit: 'Quality & Audit' tab" + tail),
        "fill": FILL_PASS if status == "PASS" else FILL_FAIL,
        "height": 30 if (tail or len(basis_short) > 90) else 18,
    }


# ON-TAB SCORE CHIP (Tristan 2026-07-03: "if they don't have a score how can you score
# it?"). EVERY tab reserves row 2 as its score chip at build time and registers itself in
# _CHIP_SPANS; the chip is RE-STAMPED at the very end of build() from the FINAL
# _TAB_SCORES (score + the formula with live counts + a pointer to Quality & Audit) —
# never at tab-build time, so the banner-timing staleness gap cannot recur. This
# supersedes the 2026-07-02 meta-tabs-only banner rule: an on-tab score is required
# precisely because a score nobody can see on the tab is indistinguishable from no score.
_CHIP_SPANS: Dict[str, int] = {}   # sheet title -> merged span of its reserved chip row
_CHIP_PLACEHOLDER = "⬤ TAB QUALITY — computed from this tab's rendered content at end of build"

# PER-CELL COMPLETENESS CONTRACT registry of every rendered table (populated by header()).
# Each entry: {sheet, row, cols}. The generic walker (_run_cell_contracts) verifies every
# data row × required column of every registered table and refuses a table whose column
# signature has no declared contract (_TABLE_CONTRACTS) — adding an uncontracted table is
# impossible.
_RENDERED_TABLES: List[dict] = []

# ═══ LIVE-FORMULA VERDICT MACHINERY (Tristan 2026-07-03: "if you look at the cell, the
# formula is just 'pass', so that's not a formula … every single column needs to have a
# deterministic check on it which says it was actually passed or not. Just putting 'pass'
# in a column with no formulas is cheating.") ═══════════════════════════════════════════
# EVERY verdict cell in the workbook is a REAL Excel formula over the cells it judges —
# the formula bar IS the check definition. Where a check compares against data not on any
# sheet (contract quantities, drawing-derived values, python-classified evidence), the
# operand is EMBEDDED: either an 'Audit: …' column beside the table (muted) or a
# provenance-labelled row on the 'Audit data' sheet — and the formula reduces to the
# comparison over those operand cells. A check whose classification is genuinely
# python-computed embeds its EVIDENCE (the fault text, '' when clean) and the formula is
# the comparison evidence="" — never a bare literal. Enforced both directions:
# _enforce_live_check_gate refuses the build on any bare PASS/FAIL/✓/✗ literal, and
# _selftest proveCatches a planted literal. ONE TRUTH: after the LibreOffice recalc the
# builder READS BACK the recalculated score cells and tab-scorecard.json carries THOSE
# values, so the python scorecard and the in-cell formulas can never disagree.

_AUDIT_SHEET_TITLE = "Audit data"
_AUDIT_OPERANDS: List[dict] = []       # {"group","label","value","provenance"}
_AUDIT_DATA_START = 6                  # first data row on the Audit data sheet (fixed layout)


def audit_operand(group: str, label: str, value, provenance: str) -> str:
    """Register a NON-SHEET operand a verdict formula depends on; returns its absolute
    ref ('Audit data'!$C$7). The 'Audit data' sheet renders every registered operand with
    its provenance, so the workbook CONTAINS everything its own verdicts depend on."""
    _AUDIT_OPERANDS.append({"group": str(group), "label": str(label), "value": value,
                            "provenance": str(provenance)})
    return f"'{_AUDIT_SHEET_TITLE}'!$D${_AUDIT_DATA_START - 1 + len(_AUDIT_OPERANDS)}"


def _xq(s, cap: int = 180) -> str:
    """Sanitise text for embedding inside an Excel formula STRING literal: double-quotes
    become apostrophes (never a quote-escape headache), newlines collapse, length capped."""
    t = re.sub(r"\s+", " ", str(s or "")).replace('"', "'").strip()
    return (t[: cap - 1] + "…") if len(t) > cap else t


def fx_verdict(conds: List[str], fail_expr: str, pass_text: str = "PASS",
               fail_prefix: str = "FAIL — ") -> str:
    """The canonical verdict formula: =IF(AND(<conds>),"PASS","FAIL — "&<fail_expr>).
    `conds` are Excel boolean terms over the cells the check judges; `fail_expr` is an
    Excel STRING expression naming why (usually the embedded evidence cell)."""
    cond = conds[0] if len(conds) == 1 else "AND(" + ",".join(conds) + ")"
    return f'=IF({cond},"{pass_text}","{fail_prefix}"&{fail_expr})'


def _fx_req_terms(refs: List[str]) -> List[str]:
    """Completeness terms for required cells: non-empty and not the '—' placeholder."""
    out: List[str] = []
    for ref in refs:
        out.append(f'LEN(TRIM({ref}&""))>0')
        out.append(f'TRIM({ref}&"")<>"—"')
    return out


def _fx_evidence_expr(ev_ref: str, structural_label: str) -> str:
    """FAIL-message expression: the embedded python evidence when present, else the
    structural fail label (the live-recompute case — an operand was corrupted)."""
    return (f'IF(LEN(TRIM({ev_ref}&""))>0,TRIM({ev_ref}&""),'
            f'"{_xq(structural_label, 120)}")')


def _cf_verdict(ws: Worksheet, rng: str) -> None:
    """Conditional formatting for a live verdict column: green on PASS, red on FAIL —
    so a formula that FLIPS on recalc recolours itself (the static build-time fill only
    reflects the build-time evaluation)."""
    from openpyxl.formatting.rule import CellIsRule
    ws.conditional_formatting.add(rng, CellIsRule(
        operator="beginsWith", formula=['"FAIL"'], fill=FILL_FAIL, font=FONT_FAIL))
    ws.conditional_formatting.add(rng, CellIsRule(
        operator="equal", formula=['"PASS"'], fill=FILL_PASS, font=FONT_PASS))
    ws.conditional_formatting.add(rng, CellIsRule(
        operator="beginsWith", formula=['"✗"'], fill=FILL_FAIL, font=FONT_FAIL))
    ws.conditional_formatting.add(rng, CellIsRule(
        operator="beginsWith", formula=['"✓"'], fill=FILL_PASS, font=FONT_PASS))


# Check-column ranges per sheet — every rendered verdict/check column registers here so
# (a) the Q&A per-tab score formulas can COUNTIF over the live verdicts, and (b) the
# no-cheating gate + selftests can walk every check cell.
_CHECK_RANGES: Dict[str, List[dict]] = {}   # sheet -> [{col,r1,r2,n_pass,n_total}]


def _register_check_range(sheet_title: str, col_letter: str, r1: int, r2: int,
                          n_pass: Optional[int] = None,
                          n_total: Optional[int] = None) -> None:
    """Register a rendered check column (verdict formulas in col_letter, rows r1..r2).
    n_pass/n_total = the build-time PASS tally, when the column carries PASS/FAIL
    verdicts — the live per-tab score formulas COUNTIF over these ranges."""
    if r2 >= r1:
        _CHECK_RANGES.setdefault(sheet_title, []).append(
            {"col": col_letter, "r1": r1, "r2": r2, "n_pass": n_pass, "n_total": n_total})


# Q&A per-tab score cells (tab title -> 'Quality & Audit'!$B$<row>) + the live floor /
# open-issue cells — registered when the Quality & Audit tab renders; the live score
# formulas + chips + verdict formulas reference them; the post-recalc read-back reads them.
_QA_SCORE_CELLS: Dict[str, str] = {}
_QA_FLOOR_CELL: List[str] = []      # single absolute ref, list for mutability
_QA_OPEN_CELL: List[str] = []
_FONT_AUDIT = Font(name="Calibri", size=8, color="808080")


def _round1(x: float) -> float:
    """HALF-UP 1-dp rounding matching Excel's ROUND(x,1) — python round() is banker's
    rounding (round(8.25,1)=8.2, Excel=8.3), and the live score formulas must reproduce
    the python scorecard exactly (ONE TRUTH read-back assert)."""
    return math.floor(float(x) * 10 + 0.5) / 10.0


def _is_invalid_formula(_s: str) -> bool:
    """A string openpyxl will store as a formula that is NOT a valid Excel formula —
    engine PROSE ("= 3.91 t/day …"), chemical formulas, OR a formula left with an UNBOUND
    symbol (a bare letter like "E" in "=B187/(2*B189*E-…)"; bare TRUE/FALSE — use
    TRUE()/FALSE()). Strip every VALID formula token; if ANY letter remains it cannot be
    a real formula → defang/refuse. Safe for genuine formulas (=…*8000/1e9, =IF(…),
    ='Inputs & Assumptions'!$B$5, =CO2 cell-ref, COUNTIF('⚠ Checks'!$F:$F,…))."""
    _t = re.sub(r'"[^"]*"', "", _s)                     # string literals — letters here are VALID
    _t = re.sub(r"'[^']*'!", "", _t)                    # sheet refs
    _t = re.sub(r"\$?[A-Z]{1,3}\$?:\$?[A-Z]{1,3}(?![A-Za-z0-9])", "", _t)  # whole-column refs ($F:$F)
    _t = re.sub(r"\$?[A-Z]{1,3}\$?\d+", "", _t)         # cell refs (incl CO2-style)
    _t = re.sub(r"[A-Za-z][A-Za-z0-9.]*\s*\(", "(", _t)  # function calls -> (
    _t = re.sub(r"\bin_[a-z0-9_]+\b", "", _t)           # known defined names
    _t = re.sub(r"\d+\.?\d*([eE][+\-]?\d+)?", "", _t)   # numbers incl scientific (1e9)
    _t = re.sub(r"[\s+\-*/^%(),:.=&<>​]", "", _t)  # operators / whitespace / zero-width
    return bool(re.search(r"[A-Za-z]", _t))


def title_row(ws: Worksheet, text: str, span: int, subtitle: str = "") -> int:
    """Write a full-width title band + reserve the row-2 score chip (re-stamped from the
    FINAL scores at end of build — every tab carries its visible score); return next free row."""
    ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=span)
    c = ws.cell(1, 1, text)
    c.font = FONT_TITLE
    c.fill = FILL_TITLE
    c.alignment = Alignment(vertical="center", horizontal="left", indent=1)
    ws.row_dimensions[1].height = 26
    nxt = 2
    # Score chip — EVERY tab. Reserved (placeholder) now, stamped from FINAL scores later.
    ws.merge_cells(start_row=nxt, start_column=1, end_row=nxt, end_column=span)
    bc = ws.cell(nxt, 1, _CHIP_PLACEHOLDER)
    bc.font = FONT_NOTE
    bc.alignment = LEFT_TOP
    ws.row_dimensions[nxt].height = 16
    _CHIP_SPANS[ws.title] = span
    nxt += 1
    if subtitle:
        ws.merge_cells(start_row=nxt, start_column=1, end_row=nxt, end_column=span)
        s = ws.cell(nxt, 1, subtitle)
        s.font = FONT_NOTE
        s.alignment = LEFT_TOP
        # Grow the merged subtitle row so a 2-3 line purpose note never clips
        # (Excel does NOT auto-grow a MERGED wrapped cell). Estimate lines from
        # the text length vs the merged width (~5.5 chars per column-width unit).
        approx_cols_wide = max(1, sum(_col_width(ws, ci) for ci in range(1, span + 1)))
        chars_per_line = max(40, approx_cols_wide * 1.05)
        lines = max(1, int(_math.ceil(len(subtitle) / chars_per_line)))
        ws.row_dimensions[nxt].height = 15 + 13 * min(lines, 4)
        nxt += 1
    return nxt + 1  # leave a blank spacer row


def _col_width(ws: Worksheet, col_idx: int) -> float:
    """Best-effort current width of a column (default 8.43 if unset)."""
    try:
        from openpyxl.utils import get_column_letter
        cd = ws.column_dimensions.get(get_column_letter(col_idx))
        if cd is not None and cd.width:
            return float(cd.width)
    except Exception:  # noqa: BLE001
        pass
    return 8.43


def header(ws: Worksheet, row: int, cols: List[str]) -> None:
    # PER-CELL COMPLETENESS CONTRACT (Tristan 2026-07-03): EVERY rendered table is
    # REGISTERED here, so the generic cell-contract walker can verify every row ×
    # required column after the build — and a table with no declared contract entry
    # is IMPOSSIBLE to ship (the walker refuses, naming the sheet + columns).
    _RENDERED_TABLES.append({"sheet": ws.title, "row": row,
                             "cols": [str(c) if c is not None else "" for c in cols]})
    for i, name in enumerate(cols, start=1):
        c = ws.cell(row, i, name)
        c.font = FONT_HEADER
        c.fill = FILL_HEADER
        c.border = BORDER
        c.alignment = Alignment(vertical="center", wrap_text=True)


def sub_banner(ws: Worksheet, row: int, text: str, span: int) -> None:
    ws.merge_cells(start_row=row, start_column=1, end_row=row, end_column=span)
    # A deliberate "=..." live-formula heading (e.g. a Spec-sheet banner referencing the
    # master tag) is written raw; everything else is defanged for display.
    val = text if (isinstance(text, str) and text.startswith("=")) else clean_cell(text)
    c = ws.cell(row, 1, val)
    c.font = FONT_SUB
    c.fill = FILL_SUB
    c.alignment = LEFT_TOP


def unverified_banner(ws: Worksheet, row: int, span: int, text: str) -> int:
    """A red, wrapped warning band spanning `span` columns at `row` — used to flag an
    economics tab as presenting an UNVERIFIED model (no real sale price derivable for
    this class). Returns the next free row. Two rows tall for the wrapped message."""
    ws.merge_cells(start_row=row, start_column=1, end_row=row + 1, end_column=span)
    c = ws.cell(row, 1, clean_cell(text))
    c.fill = FILL_FAIL
    c.font = FONT_FAIL
    c.alignment = WRAP_TOP
    return row + 2


# Number formats (#37) — kill General/scientific. Excel display masks only;
# they never change the stored value, so they are safe on live-formula cells.
FMT_GBP = "£#,##0"          # money, no decimals
FMT_GBP2 = "£#,##0.00"      # money with pence (small unit prices)
FMT_INT = "#,##0"           # counts / integers with thousands separators
FMT_DEC1 = "#,##0.0"        # one decimal (velocities, %drop, ratings)
FMT_DEC2 = "#,##0.00"       # two decimals (ratios, m/s, areas)
FMT_NUM = "#,##0.##"        # thousands sep, drops trailing zeros (62 -> "62", 2.58 -> "2.58")

# CONTENTS hyperlink target / back-link constant.
CONTENTS_SHEET = "Contents"
FONT_LINK = Font(name="Calibri", size=11, color="1F3A5F", underline="single", bold=True)

